//! Capability availability is not query coverage or a dense-readiness claim.
//! Read existing metadata only; never probe a provider or start indexing here.
use crate::service_factory::QueryServices;
use cc_db::{capability_read::CapabilitySemanticSnapshot, index_db::IndexDb};
use cc_model::{config::ProjectConfig, query::RetrievalStrategy, CcError, CcResult};
use serde_json::{json, Value};
use std::path::Path;

pub const CAPABILITY_SPEC: &str = "retrieval-capabilities-v2";

pub(crate) fn snapshot(
    project: Option<&Path>,
    db: Option<&IndexDb>,
    config: Option<&ProjectConfig>,
    services: &QueryServices,
) -> Value {
    snapshot_observing(project, db, config, services, || {})
}

// The observer is an internal seam for deterministic publication interleavings.
pub(super) fn snapshot_observing(
    project: Option<&Path>,
    db: Option<&IndexDb>,
    config: Option<&ProjectConfig>,
    services: &QueryServices,
    mut observed_root: impl FnMut(),
) -> Value {
    let strategy = config.map(|c| c.query.strategy).unwrap_or_default();
    let attached = services.semantic().is_some();
    let wired = services.semantic_wired();
    let query_opt_in = config.is_some_and(|c| c.semantic.allow_query_network);
    let query_reason = if project.is_none() {
        Some("no_project")
    } else if db.is_none() {
        Some("closed")
    } else if !config.is_some_and(|c| c.semantic.enabled) {
        Some("semantic_disabled")
    } else if !config.is_some_and(|c| c.semantic.network_opt_in) {
        Some("network_opt_in_required")
    } else if !query_opt_in {
        Some("query_network_opt_in_required")
    } else if !cfg!(feature = "semantic-http") {
        Some("semantic_http_feature_required")
    } else if !services.query_encoding_active() {
        Some("query_encoder_not_attached")
    } else {
        None
    };
    let mut result = json!({
        "has_project":project.is_some(),"has_index":false,
        "indexed_files":null,"indexed_symbols":null,
        "capabilities":{"search":false,"graph":false,"impact":false},
        "retrieval":{
            "spec":CAPABILITY_SPEC,
            "consistency":"point_in_time", "generation_scope":"observed_database_snapshot",
            "identity_validation":"not_observed", "service_state_scope":"process_observed_separately",
            "semantic_active_space":null,
            "index_state":if project.is_none(){"no_project"}else{"closed"},
            "local_state":"unavailable",
            "semantic_state":if attached{"port_attached_unverified"}else{"not_configured"},
            "dense_state":"disabled","dense_reason":"provider_and_vector_publication_not_implemented",
            "generation":null,"resolution_freshness":null,
            "query_coverage":{"state":"not_measured","scope":"per_query_not_global"},
            "query_encoding":{"configured_opt_in":query_opt_in,"network_authorized":query_reason.is_none(),"reason":query_reason,"request_scope":"nonlocal_nonempty_only"},
            "default_strategy":strategy,
            "default_effective_strategy":if strategy==RetrievalStrategy::Semantic && !attached {None}else if strategy==RetrievalStrategy::Local || !attached {Some(RetrievalStrategy::Local)}else{Some(strategy)},
            "default_query_state":if strategy==RetrievalStrategy::Semantic && !attached{"semantic_unavailable"}else{"requires_index"},
            "diagnostic_sources":{"build":"BuildExplain on index response","graph":"GraphExplain on query response","lanes":"evidence_summary.retrieval.lanes or lane_receipts","semantic":"evidence_summary.retrieval.semantic (dense lane receipt projection)","source":"evidence_summary.source_freshness","selection":"evidence_summary.selection","packing":"evidence_summary.packing"},
            "query_pins":services.query_pins(),"pin_scope":"owned_query_views_including_inflight_clones_not_request_count",
            "execution":services.pool.stats(),"execution_scope":"process_shared_not_project_local"
        }
    });
    let (Some(_project), Some(db)) = (project, db) else {
        // No live index: an attached+wired port cannot be verified against
        // anything — keep the conservative `port_attached_unverified`
        // wording, and stop claiming "publication not implemented" (the
        // wiring exists; the index is what is absent).
        if attached && wired.is_some() {
            result["retrieval"]["dense_reason"] = json!(null);
        }
        apply_semantic_degradation(&mut result, services, attached);
        return result;
    };
    // P7-014 real state machine: an attached port that came from a
    // successful composition-root wiring reports the true lifecycle states
    // (`backfilling` while the active space has live outbox work, `ready`
    // once the dense publication covers the eligible set). A bare attached
    // port (host-side injection without wiring) keeps the honest
    // `port_attached_unverified` wording; an unwired port keeps
    // `not_configured` (V18 口径零漂移). Read-only DB reads, best-effort:
    // a failed typed read keeps the conservative error/unverified result.
    let observed = (|| -> CcResult<_> {
        for _ in 0..3 {
            // Every database value comes from one short SQLite snapshot.
            // The transaction and its lease end before any fresh checkout.
            let snapshot = match db.reads().capability_snapshot(attached && wired.is_some()) {
                Err(CcError::RetrievalChanged { .. }) => continue,
                observed => observed?,
            };
            observed_root();
            let mut semantic = result.clone();
            if attached && wired.is_some() {
                if let Some(coverage) = snapshot.semantic.as_ref() {
                    apply_semantic_snapshot(&mut semantic, coverage);
                }
                #[cfg(feature = "semantic")]
                if let Some(wired_info) = wired.as_ref() {
                    apply_configured_space_snapshot(
                        &mut semantic,
                        snapshot
                            .semantic
                            .as_ref()
                            .and_then(|s| s.active_space.as_deref()),
                        wired_info,
                    );
                }
                if let Some(reason) = services
                    .semantic_worker()
                    .and_then(|state| state.failure_reason())
                {
                    semantic["retrieval"]["semantic_state"] = json!("failed");
                    semantic["retrieval"]["semantic_worker_reason"] = json!(reason);
                }
            }
            // Ordinary epochs may advance: all values remain one observation.
            // Retry only detectable database identity changes, never publish churn.
            if db
                .reads()
                .validate_capability_identity(snapshot.generation.incarnation)?
            {
                return Ok((snapshot, semantic));
            }
        }
        Err(CcError::RetrievalChanged { attempts: 3 })
    })();
    match observed {
        Ok((snapshot, semantic)) => {
            let generation = snapshot.generation;
            let freshness = snapshot.resolution_freshness;
            result = semantic;
            result["has_index"] = json!(true);
            result["indexed_files"] = json!(snapshot.indexed_files);
            result["indexed_symbols"] = json!(snapshot.indexed_symbols);
            result["capabilities"] = json!({"search":true,"graph":true,"impact":true});
            result["retrieval"]["index_state"] = json!(if snapshot.indexed_files == 0 {
                "empty"
            } else {
                "available"
            });
            result["retrieval"]["local_state"] = json!(if freshness.complete {
                "available"
            } else {
                "resolution_pending"
            });
            result["retrieval"]["generation"] = json!(generation);
            result["retrieval"]["identity_validation"] = json!("checked_at_observation_boundary");
            result["retrieval"]["semantic_active_space"] = json!(snapshot
                .semantic
                .as_ref()
                .and_then(|s| s.active_space.as_deref()));
            result["retrieval"]["resolution_freshness"] = json!(freshness);
            if strategy != RetrievalStrategy::Semantic || attached {
                result["retrieval"]["default_query_state"] =
                    json!("available_with_per_query_checks");
            }
        }
        Err(error) => {
            result["retrieval"]["index_state"] = json!("error");
            result["retrieval"]["default_query_state"] = json!("unavailable");
            result["retrieval"]["error"] = json!({"code":"capability_observation_unavailable","identity":"unverified","message":error.to_string().chars().take(512).collect::<String>(),"retryable":matches!(error,CcError::RetrievalChanged{..})});
        }
    }
    if let Some(error) = config.and_then(|c| c.query.validate().err()) {
        result["retrieval"]["default_query_state"] = json!("invalid_config");
        result["retrieval"]["local_state"] = json!("invalid_config");
        result["retrieval"]["config_error"] = json!(error.to_string());
    }
    apply_semantic_degradation(&mut result, services, attached);
    result
}

#[cfg(feature = "semantic")]
fn apply_configured_space_snapshot(
    result: &mut Value,
    active: Option<&str>,
    wired: &crate::service_factory::SemanticWiredInfo,
) {
    let expected = cc_semantic::types::VectorSpace::new(&wired.model_id, wired.dimensions)
        .and_then(|space| space.digest());
    if let (Ok(expected), Some(active)) = (expected, active) {
        if active != expected.as_str() {
            result["retrieval"]["semantic_state"] = json!("backfilling");
            result["retrieval"]["dense_state"] = json!("partial");
            result["retrieval"]["dense_reason"] = json!("semantic_configured_space_pending");
            result["retrieval"]["dense_published"] = json!(0);
        }
    }
}

// Keep the original helper fixtures and assertions intact while exercising
// the production projection with the typed database observation.
#[cfg(all(test, feature = "semantic"))]
fn apply_configured_space_state(
    result: &mut Value,
    db: &IndexDb,
    wired: &crate::service_factory::SemanticWiredInfo,
) {
    let snapshot = db.reads().capability_snapshot(true).unwrap();
    apply_configured_space_snapshot(
        result,
        snapshot
            .semantic
            .as_ref()
            .and_then(|s| s.active_space.as_deref()),
        wired,
    );
}

/// The wired-port state projection (P7-014). `semantic_state`:
/// `backfilling` while the active space has live (`pending`/`claimed`)
/// outbox work, else `ready`; live counts land in additive
/// `semantic_pending`/`semantic_failed` fields. `dense_state`: `ready` when
/// the active-space publication covers the eligible document set,
/// `partial` otherwise, with `dense_published`/`dense_desired` counts and a
/// stable `dense_reason` naming the gap. Never a ready impersonation: the
/// unwired and bare-attached wordings are byte-identical to pre-P7-014.
fn apply_semantic_snapshot(result: &mut Value, coverage: &CapabilitySemanticSnapshot) {
    if coverage.active_space.is_none() {
        result["retrieval"]["dense_reason"] = json!("semantic_no_active_space");
        return;
    }
    let pending = coverage.pending;
    let uncovered = coverage.eligible.saturating_sub(coverage.published);
    result["retrieval"]["semantic_state"] = json!(if pending > 0 {
        "backfilling"
    } else if coverage.failed > 0 {
        "failed"
    } else if uncovered > 0 {
        "backfilling"
    } else {
        "ready"
    });
    result["retrieval"]["semantic_pending"] = json!(pending);
    result["retrieval"]["semantic_failed"] = json!(coverage.failed);
    if coverage.eligible > 0 && uncovered == 0 {
        result["retrieval"]["dense_state"] = json!("ready");
        result["retrieval"]["dense_reason"] = json!(null);
    } else {
        result["retrieval"]["dense_state"] = json!("partial");
        result["retrieval"]["dense_reason"] = json!(if uncovered > 0 {
            "semantic_coverage_uncovered"
        } else {
            "semantic_no_eligible_documents"
        });
    }
    result["retrieval"]["dense_published"] = json!(coverage.published);
    result["retrieval"]["dense_desired"] = json!(coverage.eligible);
}

#[cfg(test)]
fn apply_semantic_wired(result: &mut Value, db: &IndexDb) {
    let snapshot = db.reads().capability_snapshot(true).unwrap();
    apply_semantic_snapshot(result, snapshot.semantic.as_ref().unwrap());
}

/// P6-018 degraded 透出 (P6-012 deviation-1 hand-over): when the optional
/// semantic subsystem is attached AND its degradation ledger reports
/// `degraded` (a corrupt cache artifact was detected, or the re-embed
/// budget ran out), `semantic_state` becomes `"degraded"` and the stable
/// reasons are listed under `degraded_reason` — taking precedence over the
/// P7-014 wired `ready`/`backfilling` states (a degraded cache is never
/// reported ready). Plain cache misses never degrade (cold-cache is
/// normal); an unattached port keeps `"not_configured"`; an attached port
/// without wiring evidence keeps `"port_attached_unverified"`. Read-only:
/// no cache path is probed here.
fn apply_semantic_degradation(result: &mut Value, services: &QueryServices, attached: bool) {
    if !attached {
        return;
    }
    let Some(degradation) = services.semantic_degradation() else {
        return;
    };
    if !degradation.degraded {
        return;
    }
    result["retrieval"]["semantic_state"] = json!("degraded");
    result["retrieval"]["degraded_reason"] = json!(degradation.degraded_reasons);
}

use super::*;
use cc_semantic::{
    ports::{DocumentInput, EmbeddingProvider, ProviderError, QueryInput},
    providers::fake::{FakeProvider, FakeProviderConfig},
};
use cc_server::{engine::CodeIndex, semantic_runtime::SemanticRuntime};
use std::{
    sync::{
        atomic::{AtomicUsize, Ordering},
        Arc, Condvar, Mutex,
    },
    time::{Duration, Instant},
};

struct HeldProvider {
    inner: FakeProvider,
    entered: Arc<AtomicUsize>,
    gate: Arc<(Mutex<bool>, Condvar)>,
}
impl EmbeddingProvider for HeldProvider {
    fn space(&self) -> &cc_semantic::types::VectorSpace {
        self.inner.space()
    }
    fn embed_documents(&self, input: &[DocumentInput]) -> Result<Vec<Vec<f32>>, ProviderError> {
        self.entered.fetch_add(1, Ordering::SeqCst);
        let mut released = self.gate.0.lock().unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        while !*released {
            assert!(
                Instant::now() < deadline,
                "held synthetic worker exceeded original bound"
            );
            released = self
                .gate
                .1
                .wait_timeout(released, Duration::from_millis(2))
                .unwrap()
                .0;
        }
        self.inner.embed_documents(input)
    }
    fn embed_queries(&self, input: &[QueryInput]) -> Result<Vec<Vec<f32>>, ProviderError> {
        self.inner.embed_queries(input)
    }
}
struct World {
    root: tempfile::TempDir,
    index: CodeIndex,
    db: Arc<IndexDb>,
    config: ProjectConfig,
    services: QueryServices,
    worker: Arc<SemanticRuntime>,
    gate: Arc<(Mutex<bool>, Condvar)>,
    entered: Arc<AtomicUsize>,
}
impl Drop for World {
    fn drop(&mut self) {
        self.release();
        self.worker.close();
        self.index.close();
    }
}
impl World {
    async fn held() -> Self {
        let root = tempfile::tempdir().unwrap();
        let mut config = ProjectConfig::default();
        config.auto_index.enabled = false;
        config.indexing.db_read_pool_size = Some(1);
        config.semantic.enabled = true;
        config.semantic.network_opt_in = false;
        config.semantic.allow_query_network = false;
        config.semantic.model_id = "fake/independent-status".into();
        config.semantic.dimensions = Some(2);
        config.semantic.max_input_tokens = Some(8192);
        config.semantic.max_batch_items = Some(16);
        config.semantic.endpoint = "https://semantic.invalid/v1".into();
        std::fs::write(
            root.path().join(".codecortex.json"),
            serde_json::to_vec(&config).unwrap(),
        )
        .unwrap();
        std::fs::write(root.path().join("one.rs"), "pub fn one() -> u32 { 947 }\n").unwrap();
        let mut index = CodeIndex::new(Some(root.path())).unwrap();
        index.build_index(false).unwrap();
        let db = index.index_db().unwrap().clone();
        let actual = Arc::new(cc_server::service_factory::QueryServices::default());
        let services = QueryServices(actual.clone());
        let subsystem = Arc::new(
            cc_server::semantic_wiring::assemble_with(
                &root.path().to_string_lossy(),
                &config,
                db.clone(),
                |key| {
                    (key == cc_semantic::cache::CACHE_ROOT_ENV)
                        .then(|| root.path().join("cache").to_string_lossy().into_owned())
                },
                false,
            )
            .unwrap()
            .unwrap(),
        );
        actual.set_semantic(Some(subsystem.recall.clone()));
        actual.set_semantic_wired(Some(cc_server::service_factory::SemanticWiredInfo {
            model_id: subsystem.space.model_id().to_owned(),
            dimensions: subsystem.space.dimension(),
        }));
        actual.set_semantic_degradation(Some(
            cc_server::service_factory::SemanticDegradation::from(subsystem.ledger.snapshot()),
        ));
        let entered = Arc::new(AtomicUsize::new(0));
        let gate = Arc::new((Mutex::new(false), Condvar::new()));
        let worker = SemanticRuntime::new(
            db.clone(),
            subsystem.clone(),
            actual,
            Arc::new(HeldProvider {
                inner: FakeProvider::new(FakeProviderConfig::new(subsystem.space.clone())),
                entered: entered.clone(),
                gate: gate.clone(),
            }),
        )
        .unwrap();
        assert!(worker.schedule());
        tokio::time::timeout(Duration::from_secs(5), async {
            while entered.load(Ordering::SeqCst) == 0 {
                tokio::time::sleep(Duration::from_millis(2)).await;
            }
        })
        .await
        .unwrap();
        assert_eq!(
            db.reads().semantic_coverage().unwrap().coverage.published,
            0
        );
        Self {
            root,
            index,
            db,
            config,
            services,
            worker,
            gate,
            entered,
        }
    }
    fn release(&self) {
        *self.gate.0.lock().unwrap() = true;
        self.gate.1.notify_all();
    }
    fn published(&self, minimum_calls: usize) {
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let c = self.db.reads().semantic_coverage().unwrap().coverage;
            let p = self.db.reads().semantic_outbox_pending().unwrap();
            if self.entered.load(Ordering::SeqCst) >= minimum_calls
                && c.published > 0
                && c.uncovered == 0
                && p == 0
                && self.services.query_pins() == 0
            {
                return;
            }
            assert!(
                Instant::now() < deadline,
                "publication not complete: {c:?} pending={p}"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
    }
}
fn trace(label: &str, value: Value) {
    if let Some(root) = std::env::var_os("P7_STATUS_REVIEW_EVIDENCE_DIR") {
        let root = std::path::PathBuf::from(root);
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(
            root.join(format!("{}-{label}.json", std::process::id())),
            serde_json::to_vec_pretty(&value).unwrap(),
        )
        .unwrap();
    } else {
        println!("STATUS_REVIEW {label} {value}");
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn forced_real_worker_publication_returns_complete_old_then_new_observations() {
    let world = World::held().await;
    let before = world.db.reads().read_generation().unwrap();
    let mut attempts = 0;
    let status = super::snapshot_observing(
        Some(world.root.path()),
        Some(&world.db),
        Some(&world.config),
        &world.services,
        || {
            attempts += 1;
            if attempts == 1 {
                world.release();
                world.published(1);
            }
        },
    );
    let after = world.db.reads().read_generation().unwrap();
    let coverage = world.db.reads().semantic_coverage().unwrap();
    assert_v2(&status);
    assert_eq!(before.incarnation, after.incarnation);
    assert_eq!(before.index_epoch, after.index_epoch);
    assert_eq!(before.evidence_epoch, after.evidence_epoch);
    assert!(after.semantic_epoch > before.semantic_epoch);
    assert_eq!(attempts, 1);
    assert_v2(&status);
    assert_eq!(status["retrieval"]["generation"], json!(before));
    assert_eq!(status["retrieval"]["dense_state"], "partial");
    assert_eq!(status["retrieval"]["dense_published"], 0);
    assert_eq!(
        status["retrieval"]["dense_desired"],
        coverage.coverage.eligible
    );
    assert_eq!(status["retrieval"]["semantic_pending"], 1);
    assert_eq!(status["retrieval"]["semantic_state"], "backfilling");
    assert!(!status["retrieval"]["error"].is_object());
    let settled = super::snapshot(
        Some(world.root.path()),
        Some(&world.db),
        Some(&world.config),
        &world.services,
    );
    assert_v2(&settled);
    assert_eq!(settled["retrieval"]["generation"], json!(after));
    assert_eq!(settled["retrieval"]["dense_state"], "ready");
    assert_eq!(
        settled["retrieval"]["dense_published"],
        coverage.coverage.published
    );
    assert_eq!(
        settled["retrieval"]["dense_desired"],
        coverage.coverage.eligible
    );
    assert_eq!(settled["retrieval"]["semantic_pending"], 0);
    trace(
        "forced-worker-crossing",
        json!({"before":before,"after":after,"coverage":{"generation":coverage.generation,"published":coverage.coverage.published,"eligible":coverage.coverage.eligible,"uncovered":coverage.coverage.uncovered,"failed":coverage.coverage.failed},"status":status,"root_attempts":attempts,"provider_calls":world.entered.load(Ordering::SeqCst),"real_worker":true,"level":"L2 exact-source observer"}),
    );
}
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn legacy_status_counterexample_pairs_old_root_with_new_real_publication() {
    let world = World::held().await;
    let before = world.db.reads().read_generation().unwrap();
    let mut callbacks = 0;
    let status = crate::legacy_status::snapshot_observing_legacy(
        Some(world.root.path()),
        Some(&world.db),
        Some(&world.config),
        &world.services,
        || {
            callbacks += 1;
            world.release();
            world.published(1);
        },
    );
    let after = world.db.reads().read_generation().unwrap();
    assert_eq!(callbacks, 1);
    assert!(after.semantic_epoch > before.semantic_epoch);
    assert_eq!(status["retrieval"]["generation"], json!(before));
    assert_ne!(status["retrieval"]["generation"], json!(after));
    assert_eq!(status["retrieval"]["dense_state"], "ready");
    assert_eq!(status["retrieval"]["dense_published"], 1);
    assert!(
        status["retrieval"]["generation"] == json!(before)
            && status["retrieval"]["dense_published"] != 0,
        "historical counterexample remains old-root/new-coverage and is forbidden in v2"
    );
    trace(
        "legacy-counterexample",
        json!({"before":before,"after":after,"status":status,"callbacks":callbacks,"real_worker":true,"legacy_code_with_observer_only":true,"old_ready_generation_inconsistent":true}),
    );
}
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn ordinary_real_worker_publication_never_restarts_the_statistics() {
    let mut world = World::held().await;
    world.release();
    world.published(1);
    let start = Instant::now();
    let mut committed = Vec::new();
    for poll in 0..3 {
        let before = world.db.reads().read_generation().unwrap();
        let coverage_before = world.db.reads().semantic_coverage().unwrap().coverage;
        let mut attempts = 0;
        let db = world.db.clone();
        let config = world.config.clone();
        let root = world.root.path().to_path_buf();
        let services = QueryServices(world.services.0.clone());
        let status =
            super::snapshot_observing(Some(&root), Some(&db), Some(&config), &services, || {
                attempts += 1;
                std::fs::write(
                    root.join("one.rs"),
                    format!("pub fn one() -> u32 {{ {} }}\n", 948 + poll),
                )
                .unwrap();
                world.index.build_index(false).unwrap();
                world.worker.schedule();
                world.published(poll + 2);
            });
        committed.push(db.reads().read_generation().unwrap());
        assert_eq!(attempts, 1);
        assert_v2(&status);
        assert_eq!(status["retrieval"]["index_state"], "available");
        assert_eq!(status["retrieval"]["generation"], json!(before));
        assert_eq!(
            status["retrieval"]["dense_published"],
            coverage_before.published
        );
        assert_eq!(
            status["retrieval"]["dense_desired"],
            coverage_before.eligible
        );
        assert_eq!(status["retrieval"]["dense_state"], "ready");
        assert_eq!(status["retrieval"]["semantic_pending"], 0);
        assert!(!status["retrieval"]["error"].is_object());
    }
    assert!(start.elapsed() < Duration::from_secs(3));
    assert_eq!(world.entered.load(Ordering::SeqCst), 4);
    trace(
        "point-in-time-real-worker-churn",
        json!({"observations":3,"attempts_per_observation":1,"committed":committed,"provider_calls":world.entered.load(Ordering::SeqCst),"elapsed_ms":start.elapsed().as_millis(),"real_worker":true}),
    );
}
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn stable_status_matches_coverage_and_configured_space_mismatch_stays_partial() {
    let mut world = World::held().await;
    world.release();
    world.published(1);
    let before = world.db.reads().read_generation().unwrap();
    let status = super::snapshot(
        Some(world.root.path()),
        Some(&world.db),
        Some(&world.config),
        &world.services,
    );
    assert_v2(&status);
    let coverage = world.db.reads().semantic_coverage().unwrap();
    assert_eq!(
        json!(coverage.generation),
        status["retrieval"]["generation"]
    );
    assert_eq!(status["retrieval"]["generation"], json!(before));
    assert_eq!(status["retrieval"]["dense_state"], "ready");
    assert_eq!(
        status["retrieval"]["dense_published"],
        coverage.coverage.published
    );
    assert_eq!(
        status["retrieval"]["dense_desired"],
        coverage.coverage.eligible
    );
    world.config.semantic.model_id = "fake/intended-next-space".into();
    world
        .services
        .set_semantic_wired(Some(crate::service_factory::SemanticWiredInfo {
            model_id: world.config.semantic.model_id.clone(),
            dimensions: 2,
        }));
    let mismatch = super::snapshot(
        Some(world.root.path()),
        Some(&world.db),
        Some(&world.config),
        &world.services,
    );
    assert_eq!(mismatch["retrieval"]["generation"], json!(before));
    assert_eq!(mismatch["retrieval"]["semantic_state"], "backfilling");
    assert_eq!(mismatch["retrieval"]["dense_state"], "partial");
    assert_eq!(mismatch["retrieval"]["dense_published"], 0);
    assert_eq!(
        mismatch["retrieval"]["dense_reason"],
        "semantic_configured_space_pending"
    );
    trace(
        "stable-configured-space",
        json!({"coverage":{"generation":coverage.generation,"published":coverage.coverage.published,"eligible":coverage.coverage.eligible,"uncovered":coverage.coverage.uncovered,"failed":coverage.coverage.failed},"stable":status,"mismatch":mismatch,"query_network_path_excluded":true}),
    );
}

fn assert_v2(status: &Value) {
    assert_eq!(status["retrieval"]["spec"], "retrieval-capabilities-v2");
    assert_eq!(status["retrieval"]["consistency"], "point_in_time");
    assert_eq!(
        status["retrieval"]["generation_scope"],
        "observed_database_snapshot"
    );
    assert_eq!(
        status["retrieval"]["identity_validation"],
        "checked_at_observation_boundary"
    );
    assert_eq!(
        status["retrieval"]["service_state_scope"],
        "process_observed_separately"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn degradation_overrides_ready_in_separate_process_scope() {
    let world = World::held().await;
    world.release();
    world.published(1);
    world
        .services
        .set_semantic_degradation(Some(crate::service_factory::SemanticDegradation {
            degraded: true,
            degraded_reasons: vec!["synthetic observed degradation".into()],
            ..Default::default()
        }));
    let status = super::snapshot(
        Some(world.root.path()),
        Some(&world.db),
        Some(&world.config),
        &world.services,
    );
    assert_v2(&status);
    assert_eq!(status["retrieval"]["semantic_state"], "degraded");
    assert_eq!(
        status["retrieval"]["degraded_reason"][0],
        "synthetic observed degradation"
    );
    assert_eq!(
        status["retrieval"]["dense_published"],
        status["retrieval"]["dense_desired"]
    );
    assert_eq!(
        status["retrieval"]["generation"],
        json!(world.db.reads().read_generation().unwrap())
    );
}
